/* Same Bearer auth as Chat Retention; passes the request body through. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true, body: req.body || {} } }];

/* Knowledge-base ingest / retire / list (KB-DESIGN v1.1, P1).
   Modes via request body:
     { mode: 'ingest', title, text, source_type?, source_ref? }
     { mode: 'retire', doc_id | title }
     { mode: 'list' }
   Embedding: DashScope native API, qwen3.7-text-embedding, dim 1024,
   text_type=document. Idempotent via content hash. */
const { Client } = require('pg');
const item = $input.first().json;
const body = item.body || {};
const mode = body.mode || 'ingest';

const DASHSCOPE_URL = 'https://dashscope.aliyuncs.com/api/v1/services/embeddings/text-embedding/text-embedding';
const EMBED_MODEL = 'qwen3.7-text-embedding';
const EMBED_DIM = 1024;
const BATCH = 20;                 // DashScope limit: 20 texts per call
const TARGET_CHARS = 750;         // ≈500 tokens for mixed zh/en
const OVERLAP_CHARS = 80;

const pgClient = () => new Client({
  host: $env.DB_POSTGRESDB_HOST || 'postgres',
  port: Number($env.DB_POSTGRESDB_PORT || 5432),
  database: $env.DB_POSTGRESDB_DATABASE || 'n8n',
  user: $env.DB_POSTGRESDB_USER || 'n8n',
  password: $env.DB_POSTGRESDB_PASSWORD,
});

const dashHeaders = { Authorization: 'Bearer ' + ($env.DASHSCOPE_API_KEY || ''), 'Content-Type': 'application/json' };

const apiBase = 'http://localhost:5678/api/v1';
const n8nApi = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: apiBase + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const meterTable = async () => {
  const tables = (await n8nApi('GET', '/data-tables', { limit: 100 })).data || [];
  return (tables.find((t) => t.name === 'kb_usage') || {}).id || null;
};

function chunkText(text) {
  const sections = text.split(/\n(?=#{1,6}\s)/);
  const out = [];
  for (const section of sections) {
    // only collapse horizontal whitespace; newlines are paragraph boundaries
    const flat = section.replace(/[ \t\r]+/g, ' ');
    const sents = flat.match(/[^。！？!?.；;\n]+[。！？!?.；;\n]?/g) || [flat];
    let cur = '';
    for (const s of sents) {
      if (cur && (cur + s).length > TARGET_CHARS) {
        out.push(cur.trim());
        cur = cur.slice(-Math.min(OVERLAP_CHARS, cur.length)) + s;
      } else {
        cur += s;
      }
    }
    if (cur.trim()) out.push(cur.trim());
  }
  // Fallback: text with no sentence punctuation (an English paper, typically)
  // never hits a boundary and arrives here as one enormous chunk — which would
  // mean a single vector for the whole document. Hard-split anything well over
  // target, preferring a space, keeping the overlap.
  const final = [];
  for (const c2 of out) {
    if (c2.length <= TARGET_CHARS * 1.5) { final.push(c2); continue; }
    let i = 0;
    while (i < c2.length) {
      let cut = Math.min(i + TARGET_CHARS, c2.length);
      if (cut < c2.length) {
        const sp = c2.lastIndexOf(' ', cut);
        if (sp > i + TARGET_CHARS * 0.5) cut = sp + 1;
      }
      final.push(c2.slice(i, cut).trim());
      if (cut >= c2.length) break;
      i = Math.max(cut - OVERLAP_CHARS, i + 1);
    }
  }
  return final.filter((x) => x.length > 0);
}

const vectorLiteral = (vec) => '[' + vec.join(',') + ']';

const client = pgClient();
await client.connect();

try {
  if (mode === 'list') {
    const docs = await client.query(
      `SELECT d.doc_id, d.title, d.source_type, d.status, d.created_at,
              COUNT(c.chunk_id)::int AS chunks
         FROM kb_documents d LEFT JOIN kb_chunks c ON c.doc_id = d.doc_id
        GROUP BY d.doc_id ORDER BY d.created_at DESC LIMIT 100`
    );
    return [{ json: { ok: true, mode, docs: docs.rows } }];
  }

  if (mode === 'retire') {
    const key = body.doc_id || body.title;
    if (!key) return [{ json: { ok: false, mode, error: 'doc_id or title required' } }];
    const r = await client.query(
      `UPDATE kb_documents SET status='retired', updated_at=now()
        WHERE doc_id = $1 OR title = $1 RETURNING doc_id`, [key]
    );
    return [{ json: { ok: true, mode, retired: r.rowCount } }];
  }


  // ---- mode: health — chunking sanity, so a silent regression is visible ----
  // The bug this guards against: text with no sentence punctuation used to arrive
  // as ONE chunk, so a whole document shared a single vector. It never errored —
  // retrieval just quietly got worse. This makes it fail loudly instead.
  if (mode === 'health') {
    const r = await client.query(
      `SELECT COUNT(*)::int AS chunks,
              COALESCE(MAX(LENGTH(content)), 0)::int AS max_chars,
              COALESCE(AVG(LENGTH(content)), 0)::int AS avg_chars
         FROM kb_chunks c JOIN kb_documents d ON d.doc_id = c.doc_id
        WHERE d.status = 'active'`
    );
    const docs = await client.query(`SELECT COUNT(*)::int AS n FROM kb_documents WHERE status = 'active'`);
    const h = r.rows[0] || {};
    const limit = TARGET_CHARS * 2;
    return [{ json: {
      ok: true,
      mode,
      active_docs: (docs.rows[0] || {}).n || 0,
      chunks: h.chunks || 0,
      max_chunk_chars: h.max_chars || 0,
      avg_chunk_chars: h.avg_chars || 0,
      limit_chars: limit,
      healthy: (h.max_chars || 0) <= limit
    } }];
  }

  // ---- mode: search (semantic retrieval testbench) ----
  if (mode === 'search') {
    const q = String(body.query || '').trim();
    if (!q) return [{ json: { ok: false, mode, error: 'query is required' } }];
    if (!($env.DASHSCOPE_API_KEY || '').trim()) {
      return [{ json: { ok: false, mode, error: 'DASHSCOPE_API_KEY not configured' } }];
    }
    const topK = Math.min(Math.max(Number(body.top_k) || 6, 1), 10);
    const emb = await this.helpers.httpRequest({
      method: 'POST',
      url: DASHSCOPE_URL,
      headers: dashHeaders,
      body: {
        model: EMBED_MODEL,
        input: { texts: [q] },
        parameters: { dimension: EMBED_DIM, text_type: 'query', output_type: 'dense',
          instruct: 'Given a user question about internal documents, retrieve the most relevant passages' },
      },
    });
    const vec = emb.output && emb.output.embeddings && emb.output.embeddings[0] && emb.output.embeddings[0].embedding;
    if (!vec) return [{ json: { ok: false, mode, error: 'embedding call failed' } }];
    const r = await client.query(
      `SELECT c.content, c.seq, d.title, d.doc_id,
              1 - (c.embedding <=> $1::vector) AS score
         FROM kb_chunks c JOIN kb_documents d ON d.doc_id = c.doc_id
        WHERE d.status = 'active'
        ORDER BY c.embedding <=> $1::vector LIMIT $2`,
      ['[' + vec.join(',') + ']', topK]
    );
    return [{ json: { ok: true, mode, query: q, top_k: topK,
      results: r.rows.map((row) => ({
        title: row.title, doc_id: row.doc_id, seq: Number(row.seq),
        content: String(row.content).slice(0, 800),
        score: Math.round(Number(row.score) * 10000) / 10000
      }))
    } }];
  }

  // ---- mode: ingest ----
  if (!body.title || !body.text) {
    return [{ json: { ok: false, mode, error: 'title and text are required' } }];
  }
  if (!($env.DASHSCOPE_API_KEY || '').trim()) {
    return [{ json: { ok: false, mode, error: 'DASHSCOPE_API_KEY not configured — set it in .env and restart n8n' } }];
  }

  const sha = require('crypto').createHash('sha256').update(body.text).digest('hex');
  const docId = 'kb-' + sha.slice(0, 16);
  const sourceType = body.source_type || 'text';

  const existing = await client.query('SELECT content_sha, status FROM kb_documents WHERE doc_id = $1', [docId]);
  if (existing.rows.length && existing.rows[0].content_sha === sha && existing.rows[0].status === 'active') {
    return [{ json: { ok: true, mode, action: 'skipped', doc_id: docId, reason: 'identical content already active' } }];
  }

  const chunks = chunkText(body.text);
  if (!chunks.length) {
    return [{ json: { ok: false, mode, error: 'text produced no chunks' } }];
  }

  const embeddings = [];
  let billedTokens = 0;
  for (let i = 0; i < chunks.length; i += BATCH) {
    const part = chunks.slice(i, i + BATCH);
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: DASHSCOPE_URL,
      headers: dashHeaders,
      body: {
        model: EMBED_MODEL,
        input: { texts: part },
        parameters: { dimension: EMBED_DIM, text_type: 'document', output_type: 'dense' },
      },
    });
    const out = resp.output && resp.output.embeddings ? resp.output.embeddings : null;
    if (!out || out.length !== part.length) throw new Error('unexpected embedding response shape');
    billedTokens += Number((resp.usage && resp.usage.total_tokens) || 0);
    for (const e of out) embeddings.push(e.embedding);
  }

  try {
    await client.query('BEGIN');
    await client.query(
      `INSERT INTO kb_documents (doc_id, title, source_type, source_ref, content_sha, status)
       VALUES ($1,$2,$3,$4,$5,'active')
       ON CONFLICT (doc_id) DO UPDATE SET status='active', updated_at=now()`,
      [docId, body.title, sourceType, body.source_ref || null, sha]
    );
    await client.query('DELETE FROM kb_chunks WHERE doc_id = $1', [docId]);
    for (let i = 0; i < chunks.length; i++) {
      await client.query(
        `INSERT INTO kb_chunks (doc_id, seq, content, n_tokens, embedding) VALUES ($1,$2,$3,$4,$5::vector)`,
        [docId, i, chunks[i], Math.round(chunks[i].length / 1.5), vectorLiteral(embeddings[i])]
      );
    }
    await client.query('COMMIT');
  } catch (e) {
    await client.query('ROLLBACK');
    return [{ json: { ok: false, mode, error: 'db failure: ' + String(e.message).slice(0, 200) } }];
  }

  let cumulative = null;
  try {
    const mt = await meterTable();
    if (mt) {
      const cur = (await n8nApi('GET', `/data-tables/${mt}/rows`, { limit: 1 })).data || [];
      const old = Number(cur[0]?.total_embed_tokens || 0);
      const total = old + billedTokens;
      if (cur[0]) {
        await n8nApi('PATCH', `/data-tables/${mt}/rows/update`, null, { filter: { type: 'and', filters: [{ columnName: 'id', condition: 'eq', value: cur[0].id }] }, data: { total_embed_tokens: total } });
      } else if (billedTokens > 0) {
        await n8nApi('POST', `/data-tables/${mt}/rows`, null, { data: [{ total_embed_tokens: total }] });
      }
      cumulative = total;
    }
  } catch (e) { /* meter best-effort */ }
  return [{ json: { ok: true, mode, action: existing.rows.length ? 'updated' : 'created', doc_id: docId, chunks: chunks.length, tokens_billed: billedTokens || Math.round(body.text.length / 1.5), cumulative_embed_tokens: cumulative } }];
} catch (e) {
  return [{ json: { ok: false, mode, error: String(e && e.message ? e.message : e).slice(0, 300) } }];
} finally {
  await client.end();
}
